const wfs = $('Get All Workflows').all().map(i => i.json).filter(w => /^ThesisLab/i.test(String(w.name || '')));
const rows = $('Load Experiment Records').all().map(i => i.json).filter(r => r && r.experiment_id);
const stamp = $now.setZone('America/New_York').toFormat('yyyy-MM-dd HH:mm') + ' ET';

function slug(name) {
  return String(name).replace(/^ThesisLab\s*-\s*/i, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'workflow';
}
function cleanText(s) {
  let t = String(s || '');
  const cut = t.search(/\n\s*--|\n\s*(Best|Thanks|Regards|Cheers|Sent from)\b/i);
  if (cut > 0) t = t.slice(0, cut);
  t = t.replace(/\+?\d[\d\s().-]{8,}\d/g, '[phone removed]');
  return t.trim();
}
function b64(s) { return Buffer.from(s, 'utf8').toString('base64'); }

const files = [];
const list = [];
for (const w of wfs) {
  const clean = {
    id: w.id,
    name: w.name,
    active: !!w.active,
    nodes: w.nodes || [],
    connections: w.connections || {},
    settings: w.settings || {},
    tags: w.tags || [],
    updatedAt: w.updatedAt,
  };
  const path = 'workflows/' + slug(w.name) + '.json';
  files.push({ path, content: JSON.stringify(clean, null, 2) + '\n' });
  list.push('| ' + w.name + ' | ' + (w.active ? 'Published' : 'Draft') + ' | [' + path + '](' + path + ') |');
}

const records = rows.map(r => {
  const o = Object.assign({}, r);
  o.thesis = cleanText(o.thesis);
  return o;
});
files.push({ path: 'data/thesislab_experiments.json', content: JSON.stringify(records, null, 2) + '\n' });

const cols = [];
for (const r of records) for (const k of Object.keys(r)) if (cols.indexOf(k) < 0) cols.push(k);
const q = v => {
  const s = v === null || v === undefined ? '' : (typeof v === 'object' ? JSON.stringify(v) : String(v));
  return '"' + s.replace(/"/g, '""') + '"';
};
const csv = [cols.map(q).join(',')].concat(records.map(r => cols.map(c => q(r[c])).join(','))).join('\n') + '\n';
files.push({ path: 'data/thesislab_experiments.csv', content: csv });

const schema = {
  table: 'thesislab_experiments',
  columns: [
    ['experiment_id', 'string'], ['status', 'string'], ['thesis', 'string'], ['asset', 'string'],
    ['benchmark', 'string'], ['direction', 'string'], ['horizon_days', 'number'], ['falsifiable_claim', 'string'],
    ['strategy_json', 'string'], ['notional_usd', 'number'], ['order_id', 'string'], ['order_status', 'string'],
    ['proposed_at', 'date'], ['decided_at', 'date'], ['outcome', 'string'], ['last_error', 'string'],
    ['close_order_id', 'string'], ['closed_at', 'date'],
  ].map(c => ({ name: c[0], type: c[1] })),
};
files.push({ path: 'data/schema.json', content: JSON.stringify(schema, null, 2) + '\n' });

const readme = [
  '# ThesisLab',
  '',
  'Every thesis is a falsifiable experiment. Paper trading only.',
  '',
  'ThesisLab turns a plain-English investment thesis into a testable paper-trading experiment, built in n8n for NYU Stern OPMG-UB 30-001 (Foundations of AI Agents).',
  'Arthur Voss, a fictional old-school Wall Street researcher (disciplined, skeptical, evidence-driven, slightly contrarian), is the research partner. The character affects tone only; it never overrides safety rules or data requirements.',
  '',
  '## Guardrails',
  '- Alpaca **paper** trading only. No live endpoint, no live credentials.',
  '- No order without explicit human approval (APPROVE <experiment id>).',
  '- V1 is long-only U.S. equities. No options, leverage, shorts, or crypto.',
  '- Prices, fills and results come only from tools. Nothing is invented.',
  '- Failures fail closed and alert the owner.',
  '',
  '## Workflows',
  '| Workflow | State | File |',
  '|---|---|---|',
].concat(list).concat([
  '',
  '## Data',
  '- data/thesislab_experiments.json and .csv: every thesis, bet, order status and verdict (email signatures and phone numbers stripped).',
  '- data/schema.json: column definitions for the n8n data table.',
  '',
  '## Restoring',
  'In n8n, create a workflow, open the menu, choose Import from File and pick a file from workflows/. Credentials are referenced by name only; reconnect your own Alpaca (paper), OpenAI, Pinecone, Gmail, Telegram and Twilio accounts after import. No API keys are stored in this repository.',
  '',
  '_Last synced ' + stamp + ' by the ThesisLab - GitHub Backup workflow._',
  '',
]).join('\n');
files.unshift({ path: 'README.md', content: readme });

return files.map(f => ({ json: { path: f.path, b64: b64(f.content), bytes: f.content.length, synced_at: stamp } }));

const built = $('Build Files').all().map(i => i.json);
const remote = $input.all().map(i => i.json || {});
return built.map((f, idx) => {
  const r = remote[idx] || {};
  const sha = typeof r.sha === 'string' ? r.sha : '';
  const current = String(r.content || '').replace(/\n/g, '');
  return { json: { path: f.path, b64: f.b64, synced_at: f.synced_at, sha, changed: current !== f.b64 } };
});
